// Only you may talk to this agent. Put your own WhatsApp number here, digits only with
// country code and no "+" (the format WhatsApp sends in "from"), e.g. '15551234567'.
// While this is empty every message is ignored.
const ALLOWED_SENDER = '<PARV_WHATSAPP_NUMBER>';

const out = [];
for (const item of $input.all()) {
  for (const msg of item.json.messages || []) {
    if (!ALLOWED_SENDER || msg.from !== ALLOWED_SENDER) continue;
    if (msg.type !== 'text' || !msg.text?.body) continue;
    const text = msg.text.body.trim();
    // "approve" / "deny" (optionally with a request id, e.g. "approve ab12cd") is handled by the workflow itself,
    // never by the agent. Without an id it applies to the one request waiting.
    const m = text.match(/^(approve|deny)(?:\s+([0-9a-f]{6}))?[.!]?$/i);
    out.push({ json: {
      from: msg.from,
      phoneNumberId: item.json.metadata.phone_number_id,
      prompt: text,
      isApproval: !!m,
      decision: m ? m[1].toLowerCase() : null,
      requestId: m && m[2] ? m[2].toLowerCase() : null,
    } });
  }
}
return out;

// Hand the result of the approved (or denied) command back to the agent so it can carry on
const msg = $('Parse message').first().json;
return [{ json: {
  prompt: `[Automatic note, not typed by the user] The user replied "${[msg.decision, msg.requestId].filter(Boolean).join(' ')}". ` +
    `Host response: ${JSON.stringify($json)}. Tell the user the outcome briefly and continue the task if there is more to do.`,
} }];

// Put the parsed message back, with the pipeline's recent notifications attached for the agent's prompt
const messages = $('Parse message').all();
return $input.all().map((item, i) => ({ json: {
  ...messages[i].json,
  notifications: Array.isArray(item.json.notifications) ? item.json.notifications : [],
} }));
